package interfaces;
import estruturas.*;import model.*;import javax.swing.*;import javax.swing.table.*;import java.awt.*;
public class PainelInscricoes extends JPanel{
 final TabelaHash estudantes;final ArvoreAVL disciplinas;final GestaoInscricoes gestao;final JComboBox<Item> aluno=new JComboBox<>(),disc=new JComboBox<>();final JComboBox<String> estado=new JComboBox<>(new String[]{"Todas","Activas","Canceladas"});final DefaultTableModel modelo;final JTable tabela;final TableRowSorter<DefaultTableModel> filtro;final JLabel count=Estilo.label("",13,false,Estilo.MUTED);
 public PainelInscricoes(TabelaHash e,ArvoreAVL d,GestaoInscricoes g){estudantes=e;disciplinas=d;gestao=g;setLayout(new BorderLayout());JPanel page=Estilo.page("Gestão de Inscrições","Inscreva estudantes e acompanhe o estado das inscrições.","clip");add(page);JPanel content=Estilo.clear(new BorderLayout(0,18));page.add(content);
 Estilo.Rounded form=Estilo.card(new BorderLayout(0,12));form.add(Estilo.label("Nova inscrição",18,true,Estilo.TEXT),BorderLayout.NORTH);JPanel controls=Estilo.clear(new GridBagLayout());GridBagConstraints c=new GridBagConstraints();c.gridy=0;c.insets=new Insets(0,6,0,8);c.anchor=GridBagConstraints.WEST;c.gridx=0;controls.add(Estilo.label("Estudante",13,true,Estilo.TEXT),c);c.gridx=1;c.weightx=1;c.fill=GridBagConstraints.HORIZONTAL;controls.add(aluno,c);c.gridx=2;c.weightx=0;c.fill=GridBagConstraints.NONE;controls.add(Estilo.label("Disciplina",13,true,Estilo.TEXT),c);c.gridx=3;c.weightx=1;c.fill=GridBagConstraints.HORIZONTAL;controls.add(disc,c);c.gridx=4;c.weightx=0;c.fill=GridBagConstraints.NONE;JButton inscrever=Estilo.btn("Inscrever","plus",Estilo.BLUE);controls.add(inscrever,c);form.add(controls);content.add(form,BorderLayout.NORTH);
 Estilo.Rounded list=Estilo.card(new BorderLayout(0,16));JPanel bar=Estilo.clear(new BorderLayout());JPanel left=Estilo.actions();left.add(Estilo.label("Inscrições registadas",18,true,Estilo.TEXT));left.add(estado);bar.add(left,BorderLayout.WEST);JPanel right=Estilo.actions();JButton cancel=Estilo.btn("Cancelar inscrição","x",Estilo.RED),reload=Estilo.outline("Recarregar","refresh");right.add(cancel);right.add(reload);bar.add(right,BorderLayout.EAST);list.add(bar,BorderLayout.NORTH);
 modelo=new DefaultTableModel(new String[]{"Estudante","Disciplina","Data","Estado"},0){public boolean isCellEditable(int r,int col){return false;}};tabela=new JTable(modelo);Estilo.table(tabela);tabela.getColumnModel().getColumn(0).setPreferredWidth(250);tabela.getColumnModel().getColumn(1).setPreferredWidth(270);filtro=new TableRowSorter<>(modelo);tabela.setRowSorter(filtro);list.add(Estilo.scroll(tabela));list.add(count,BorderLayout.SOUTH);content.add(list);estado.addActionListener(ev->filtrar());inscrever.addActionListener(ev->inscrever());cancel.addActionListener(ev->cancelar());reload.addActionListener(ev->actualizarTabela());actualizarTabela();}
 public void actualizarTabela(){String codE=code(aluno),codD=code(disc);aluno.removeAllItems();disc.removeAllItems();for(Estudante e:estudantes.listar())aluno.addItem(new Item(e.getCodigo(),e.getNome()));for(Disciplina d:disciplinas.listar())disc.addItem(new Item(d.getCodigo(),d.getNome()));select(aluno,codE);select(disc,codD);modelo.setRowCount(0);for(Inscricao i:gestao.listar()){Estudante e=estudantes.buscar(i.getCodigoEstudante());Disciplina d=disciplinas.buscar(i.getCodigoDisciplina());modelo.addRow(new Object[]{i.getCodigoEstudante()+" — "+(e==null?"Removido":e.getNome()),i.getCodigoDisciplina()+" — "+(d==null?"Removida":d.getNome()),i.getDataInscricao(),i.getEstado()});}filtrar();}
 private String code(JComboBox<Item> cb){Item x=(Item)cb.getSelectedItem();return x==null?null:x.code;}
 private void select(JComboBox<Item> cb,String value){if(value==null)return;for(int i=0;i<cb.getItemCount();i++)if(cb.getItemAt(i).code.equals(value)){cb.setSelectedIndex(i);return;}}
 private void filtrar(){String s=(String)estado.getSelectedItem();if(s==null)s="Todas";final String filtroActual=s;filtro.setRowFilter(new RowFilter<DefaultTableModel,Integer>(){public boolean include(Entry<? extends DefaultTableModel,? extends Integer> e){String n=e.getStringValue(3);return filtroActual.equals("Todas")||filtroActual.equals("Activas")&&n.equalsIgnoreCase("Ativa")||filtroActual.equals("Canceladas")&&n.equalsIgnoreCase("Cancelada");}});count.setText(tabela.getRowCount()+" inscrição(ões) visível(is)");}
 private void inscrever(){Item e=(Item)aluno.getSelectedItem(),d=(Item)disc.getSelectedItem();if(e==null||d==null){Estilo.warn(this,"Registe pelo menos um estudante e uma disciplina.");return;}if(!gestao.inscrever(e.code,d.code)){Estilo.warn(this,"Inscrição já activa ou dados inexistentes.");return;}actualizarTabela();Estilo.msg(this,"Inscrição efectuada com sucesso!");}
 private void cancelar(){int r=tabela.getSelectedRow();if(r<0){Estilo.warn(this,"Seleccione uma inscrição na tabela.");return;}int m=tabela.convertRowIndexToModel(r);String e=modelo.getValueAt(m,0).toString().split(" — ",2)[0],d=modelo.getValueAt(m,1).toString().split(" — ",2)[0];if(!modelo.getValueAt(m,3).toString().equalsIgnoreCase("Ativa")){Estilo.warn(this,"Esta inscrição já está cancelada.");return;}if(!Estilo.yes(this,"Cancelar a inscrição de "+e+" em "+d+"?"))return;if(!gestao.cancelar(e,d)){Estilo.warn(this,"Não foi possível cancelar.");return;}actualizarTabela();Estilo.msg(this,"Inscrição cancelada com sucesso.");}
 private static class Item{final String code,name;Item(String a,String b){code=a;name=b;}public String toString(){return code+" — "+name;}}
}
